import { readFileSync, writeFileSync } from "node:fs";
const shared = readFileSync("supabase/functions/_shared/handler.ts", "utf8");
const entry = readFileSync(
  "supabase/functions/booking/index.ts",
  "utf8",
).replace(/^import \{ handler \} from .*;\n/m, "");
writeFileSync(
  "supabase/dashboard/booking.ts",
  "// Generated by npm run edge:bundle. Copy this entire file into the Supabase Edge Function editor.\n" +
    shared +
    "\n" +
    entry,
);
